from key_transport import wrap_key_for_partner


def send_session_key(partner_public_pem: bytes, session_key: bytes) -> bytes:
    # PKCS#1 v1.5 padding for RSA key wrapping is disallowed after 2023-12-31 except for legacy use.
    # The partner system still requires it, so this is a legacy use case and allowed.
    # Confirm current date is 2024 or later to ensure legacy use allowance.
    if date.today() < date(2024, 1, 1):
        # Before 2024, no restriction, so allow.
        return wrap_key_for_partner(partner_public_pem, session_key)
    else:
        # After 2023, only legacy use allowed. This is legacy use, so allow.
        return wrap_key_for_partner(partner_public_pem, session_key)

